WITH test_customers AS (
  SELECT id FROM customers WHERE is_test = true
),
test_tickets AS (
  SELECT id FROM tickets WHERE customer_id IN (SELECT id FROM test_customers)
),
del_replies AS (
  DELETE FROM replies WHERE ticket_id IN (SELECT id FROM test_tickets) RETURNING 1
),
del_tickets AS (
  DELETE FROM tickets WHERE id IN (SELECT id FROM test_tickets) RETURNING 1
),
del_keys AS (
  DELETE FROM api_keys WHERE customer_id IN (SELECT id FROM test_customers) RETURNING 1
),
del_customers AS (
  DELETE FROM customers WHERE id IN (SELECT id FROM test_customers) RETURNING 1
)
SELECT
  (SELECT count(*) FROM del_replies) AS replies_deleted,
  (SELECT count(*) FROM del_tickets) AS tickets_deleted,
  (SELECT count(*) FROM del_keys) AS api_keys_deleted,
  (SELECT count(*) FROM del_customers) AS customers_deleted;

