  select id from public.tickets where customer_id in (select id from test_customers)
),
del_replies as (
  delete from public.replies where ticket_id in (select id from doomed_tickets) returning 1
),
del_tickets as (
  delete from public.tickets where id in (select id from doomed_tickets) returning 1
),
del_keys as (
  delete from public.api_keys where customer_id in (select id from test_customers) returning 1
),
del_customers as (
