tt AS (SELECT id FROM public.tickets WHERE customer_id IN (SELECT id FROM tc)),
dr AS (DELETE FROM public.replies WHERE ticket_id IN (SELECT id FROM tt) RETURNING 1),
dt AS (DELETE FROM public.tickets WHERE id IN (SELECT id FROM tt) RETURNING 1),
dk AS (DELETE FROM public.api_keys WHERE customer_id IN (SELECT id FROM tc) RETURNING 1),
dc AS (DELETE FROM public.customers WHERE id IN (SELECT id FROM tc) RETURNING 1)
SELECT (SELECT count(*) FROM dr) AS replies_deleted, (SELECT count(*) FROM dt) AS tickets_deleted, (SELECT count(*) FROM dk) AS api_keys_deleted, (SELECT count(*) FROM dc) AS customers_deleted;
COMMIT;

